function icon(string $name): string {
 $paths=['grid'=>'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>','box'=>'<path d="m12 3 9 5v8l-9 5-9-5V8zM3 8l9 5 9-5M12 13v8M7.5 5.5l9 5"/>','users'=>'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m2 10v-3a6 6 0 0 0-3-5"/>','truck'=>'<path d="M3 6h11v11H3zM14 10h4l3 4v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>','chart'=>'<path d="M4 3v17h17M8 15v-4m5 4V6m5 9V9"/>','search'=>'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>','arrow'=>'<path d="M5 12h14m-5-5 5 5-5 5"/>','plus'=>'<path d="M12 5v14M5 12h14"/>','download'=>'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>','check'=>'<path d="m5 12 4 4L19 6"/>','clock'=>'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','wallet'=>'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8V5l14-3v3m4 6h-6v5h6m-3-2.5h.01"/>','logout'=>'<path d="M9 4H4v16h5m5-13 5 5-5 5M8 12h11"/>','pin'=>'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>','menu'=>'<path d="M4 6h16M4 12h16M4 18h16"/>'];
 return '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['box']).'</svg>';
}
function badge(string $status): string { return '<span class="badge '.$status.'"><i></i>'.e(STATUSES[$status]).'</span>'; }
function orderTable(array $rows): void { ?>
<div class="table-scroll"><table><thead><tr><th>Mã đơn hàng</th><th>Người gửi / Người nhận</th><th>Địa chỉ giao</th><th>Trạng thái</th><th>Thu hộ (COD)</th><th>Nhân viên</th><th></th></tr></thead><tbody>
