<?php if(!$rows): ?><tr><td colspan="7"><div class="empty"><?=icon('box')?><h3>Chưa có đơn hàng</h3><p>Thử bộ lọc khác hoặc tạo đơn hàng đầu tiên.</p><a class="btn primary" href="/?page=new">Tạo đơn hàng</a></div></td></tr><?php endif ?></tbody></table></div>
<?php } ?>
