data-confirm="Xác nhận đã đối soát và thanh toán COD cho khách hàng?"><?=csrf()?><input type="hidden" name="action" value="settle"><input type="hidden" name="id" value="<?=$o['id']?>"><button class="btn primary full">Xác nhận đối soát COD</button></form><?php endif ?></section><section class="panel form-panel"><h2>Nhân viên giao hàng</h2><p><strong><?=e($o['driver_name']?:'Chưa phân công')?></strong><br><span class="muted"><?=e($o['driver_phone'])?></span></p><?php if(!in_array($o['status'],['delivered','cancelled'])): ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="assign"><input type="hidden" name="id" value="<?=$o['id']?>"><label>Phân công cho<select name="driver_id" required><option value="">Chọn nhân viên</option><?php foreach($drivers as $d):if(!$d['active'])continue; ?><option value="<?=$d['id']?>" <?=$o['driver_id']==$d['id']?'selected':''?>><?=e($d['name'])?></option><?php endforeach ?></select></label><button class="btn full">Lưu phân công</button></form><?php endif ?></section><?php if(NEXT_STATUS[$o['status']]): ?><section class="panel form-panel"><h2>Cập nhật trạng thái</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$o['id']?>"><label>Trạng thái tiếp theo<select name="status" required><?php foreach(NEXT_STATUS[$o['status']] as $s): ?><option value="<?=$s?>"><?=STATUSES[$s]?></option><?php endforeach ?></select></label><label>Ghi chú<textarea name="note" maxlength="500" rows="2" placeholder="Lý do hoặc thông tin bổ sung"></textarea></label><button class="btn primary full">Cập nhật đơn hàng</button></form></section><?php endif ?></div></div><?php endif ?>
