<div class="page-heading"><div><span class="eyebrow">KẾT NỐI & ĐỒNG HÀNH</span><h1><?=$titles[$page]?></h1><p><?=$isCustomer?'Lưu giữ thông tin người gửi, tạo đơn thuận tiện hơn.':'Đội ngũ mang niềm tin đến từng địa chỉ.'?></p></div><span class="chip"><?=count($list)?> <?=$isCustomer?'khách hàng':'nhân viên'?></span></div><div class="management-grid"><section class="panel"><div class="panel-heading"><h2>Danh sách <?=$isCustomer?'khách hàng':'nhân viên'?></h2></div><div class="table-scroll"><table><thead><tr><th>Họ tên</th><th>Điện thoại</th><th><?=$isCustomer?'Địa chỉ':'Biển số xe'?></th><?php if(!$isCustomer): ?><th>Trạng thái</th><?php endif ?><th></th></tr></thead><tbody><?php foreach($list as $r): ?><tr><td><strong><?=e($r['name'])?></strong></td><td><a href="tel:<?=e($r['phone'])?>"><?=e($r['phone'])?></a></td><td><?=e($r[$isCustomer?'address':'vehicle'])?></td><?php if(!$isCustomer): ?><td><span class="badge <?=$r['active']?'delivered':'cancelled'?>"><?=$r['active']?'Hoạt động':'Tạm nghỉ'?></span></td><?php endif ?><td><a class="text-link" href="/?page=<?=$page?>&edit=<?=$r['id']?>">Sửa</a></td></tr><?php endforeach ?><?php if(!$list): ?><tr><td colspan="5" class="empty">Chưa có dữ liệu. Thêm thông tin ở biểu mẫu bên cạnh.</td></tr><?php endif ?></tbody></table></div></section><section class="panel form-panel"><h2><?=$edit?'Chỉnh sửa':'Thêm mới'?> <?=$isCustomer?'khách hàng':'nhân viên'?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="<?=$isCustomer?'customer':'driver'?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label>Họ tên <em>*</em><input name="name" required maxlength="100" value="<?=e($error?($_POST['name']??''):($edit['name']??''))?>" placeholder="Nhập họ tên"></label><label>Số điện thoại <em>*</em><input type="tel" name="phone" required maxlength="25" value="<?=e($error?($_POST['phone']??''):($edit['phone']??''))?>" placeholder="09xx xxx xxx"></label><?php $f=$isCustomer?'address':'vehicle'; ?><label><?=$isCustomer?'Địa chỉ':'Biển số xe'?> <em>*</em><input name="<?=$f?>" required maxlength="<?=$isCustomer?255:30?>" value="<?=e($error?($_POST[$f]??''):($edit[$f]??''))?>"></label><?php if(!$isCustomer): ?><label class="checkbox"><input type="checkbox" name="active" value="1" <?=($error?isset($_POST['active']):(!$edit||$edit['active']))?'checked':''?>> Đang hoạt động</label><?php endif ?><button class="btn primary full"><?=icon('check')?>Lưu thông tin</button><?php if($edit): ?><a class="btn full" href="/?page=<?=$page?>">Hủy chỉnh sửa</a><?php endif ?></form></section></div>
<?php elseif($page==='reports'): ?>
<div class="page-heading"><div><span class="eyebrow">HIỆU QUẢ VẬN HÀNH</span><h1>Báo cáo & đối soát</h1><p>Số liệu toàn thời gian, cập nhật trực tiếp từ đơn hàng.</p></div><a class="btn" href="/?page=export"><?=icon('download')?>Xuất dữ liệu</a></div><div class="stats-grid"><?php foreach([['Doanh thu phí giao',money($stats['revenue']),'wallet'],['COD chờ đối soát',money($stats['unsettled']),'clock'],['Tỷ lệ giao thành công',($stats['total']?round($stats['delivered']/$stats['total']*100,1):0).'%','check'],['Đơn giao thất bại',$stats['failed'],'box']] as [$label,$val,$ic]): ?><section class="stat-card"><div class="stat-top"><span><?=$label?></span><span class="stat-icon green"><?=icon($ic)?></span></div><strong class="stat-value"><?=$val?></strong><small><?=$label==='Doanh thu phí giao'?'Chỉ tính đơn đã giao':'Trên toàn bộ đơn hàng'?></small></section><?php endforeach ?></div><section class="panel"><div class="panel-heading"><div><h2>Hiệu suất nhân viên</h2><p>Tổng đơn đã phân công và phí giao từ đơn thành công</p></div></div><div class="table-scroll"><table><thead><tr><th>Nhân viên</th><th>Tổng đơn</th><th>Đang giao</th><th>Đã giao</th><th>Thất bại</th><th>Phí giao đã hoàn thành</th></tr></thead><tbody><?php foreach(query("SELECT d.name,COUNT(o.id) total,COALESCE(SUM(o.status='shipping'),0) shipping,COALESCE(SUM(o.status='delivered'),0) delivered,COALESCE(SUM(o.status='failed'),0) failed,COALESCE(SUM(CASE WHEN o.status='delivered' THEN o.fee ELSE 0 END),0) revenue FROM drivers d LEFT JOIN orders o ON o.driver_id=d.id GROUP BY d.id,d.name ORDER BY delivered DESC")->fetchAll() as $r): ?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=$r['total']?></td><td><?=$r['shipping']?></td><td class="green-text"><?=$r['delivered']?></td><td><?=$r['failed']?></td><td><?=money($r['revenue'])?></td></tr><?php endforeach ?></tbody></table></div></section><section class="panel"><div class="panel-heading"><div><h2>COD cần đối soát</h2><p>Chọn đơn để xác nhận đã thanh toán COD cho khách hàng</p></div><span class="chip"><?=money($stats['unsettled'])?></span></div><?php orderTable(query("SELECT o.*,c.name customer_name,d.name driver_name".$base." WHERE o.status='delivered' AND o.cod_settled=0 ORDER BY o.delivered_at DESC")->fetchAll()); ?></section>
<?php endif ?>
